const negativeEntries = (map) => {
  const result = {};
  for (const key of Object.keys(map)) {
    result[`-${key}`] = `calc(-1 * ${map[key]})`;
  }
  return result;
};

// Unified design scale using t-shirt sizes with rem units for accessibility.
// This scale is used for spacing to create visual harmony
// and consistent proportions throughout the design system.
const SIZE_MAP = {
  xxs: "var(--navi-xxs)",
  xs: "var(--navi-xs)",
  s: "var(--navi-s)",
  m: "var(--navi-m)",
  l: "var(--navi-l)",
  xl: "var(--navi-xl)",
  xxl: "var(--navi-xxl)",
};
Object.assign(SIZE_MAP, negativeEntries(SIZE_MAP));
const TYPO_SIZE_MAP = {
  xxs: "var(--navi-typo-xxs)",
  xs: "var(--navi-typo-xs)",
  s: "var(--navi-typo-s)",
  m: "var(--navi-typo-m)",
  l: "var(--navi-typo-l)",
  xl: "var(--navi-typo-xl)",
  xxl: "var(--navi-typo-xxl)",
};
Object.assign(TYPO_SIZE_MAP, negativeEntries(TYPO_SIZE_MAP));
const sizeSpacingKeySet = new Set(Object.keys(SIZE_MAP));
export const isSizeSpacingKey = (key) => {
  return sizeSpacingKeySet.has(key);
};
// Viewport-relative units, resolved to pixels here because a JS consumer (popup
// positioning) needs an actual number, not a length only CSS can evaluate.
// "vvw"/"vvh" are navi's own: the *visual* viewport, which — unlike vw/dvw —
// shrinks when the mobile virtual keyboard opens (see layout/responsive.js), so
// they are what a popup meant to stay clear of the keyboard should use.
// "appw"/"apph" are the same thing narrowed to the app's own screen: identical
// to vvw/vvh until the app declares --navi-app-max-width, and a share of that
// width afterwards. A gap meant to read as "a small margin" must use these —
// 3vvw on a 1500px window is a 45px gap around a 600px app.
// Functions rather than the signals themselves: appw/apph are not a signal to
// read but a value to compute (a signal, then a CSS var read back). Reading the
// signal inside still registers the same dependency for a caller doing this
// during a render.
const VIEWPORT_UNIT_VALUES = {
  appw: getAppWidth,
  apph: getAppHeight,
  vvw: () => visualViewportWidthSignal.value,
  vvh: () => visualViewportHeightSignal.value,
  vw: () => windowWidthSignal.value,
  vh: () => windowHeightSignal.value,
  dvw: () => windowWidthSignal.value,
  dvh: () => windowHeightSignal.value,
};
const VIEWPORT_LENGTH_REGEX =
  /^(-?\d+(?:\.\d+)?)(appw|apph|vvw|vvh|dvw|dvh|vw|vh)$/;
const resolveViewportLength = (size) => {
  if (typeof size !== "string") {
    return null;
  }
  const match = VIEWPORT_LENGTH_REGEX.exec(size);
  if (!match) {
    return null;
  }
  const [, amount, unit] = match;
  return (parseFloat(amount) / 100) * VIEWPORT_UNIT_VALUES[unit]();
};

// "3cqw"/"2cqh" — a share of the container the given element lives in, the way
// vvw/vvh are a share of the viewport. The caller passes the element, not the
// container: which box actually contains it is a question with one answer
// (getPositionedParent), and asking every caller to answer it themselves is how
// two of them end up disagreeing. Resolved here rather than left to CSS because
// a caller asking for a number (a placement, a slot) cannot wait for the
// cascade, and a container query unit means nothing to getComputedStyle.
const CONTAINER_LENGTH_REGEX = /^(-?[0-9.]+)cq([wh])$/;
const resolveContainerLength = (size, element) => {
  if (typeof size !== "string") {
    return null;
  }
  const match = CONTAINER_LENGTH_REGEX.exec(size.trim());
  if (!match) {
    return null;
  }
  const [, amount, axis] = match;
  const container = element
    ? getPositionedParent(element)
    : document.documentElement;
  const containerSize =
    axis === "w" ? container.clientWidth : container.clientHeight;
  return (parseFloat(amount) / 100) * containerSize;
};

export const resolveSpacingSize = (size, element, property = "padding") => {
  const viewportLength = resolveViewportLength(size);
  if (viewportLength !== null) {
    return viewportLength;
  }
  const containerLength = resolveContainerLength(size, element);
  if (containerLength !== null) {
    return containerLength;
  }
  return normalizeStyle(SIZE_MAP[size] || size, property, "js", element);
};
export const resolveTypoSize = (size, element, property = "fontSize") => {
  return normalizeStyle(TYPO_SIZE_MAP[size] || size, property, "js", element);
};

